```python
def is_valid_sudoku_enhanced(grid):
    """
    Validates a 9x9 Sudoku grid with comprehensive checks:
    1. Number range validation (1-9 or 0 for empty)
    2. Row/column/box uniqueness checks
    3. Early termination for invalid cases
    Returns: (is_valid, error_message)
    """
    # Validate number range and type
    for row in grid:
        for num in row:
            if not isinstance(num, int) or num < 0 or num > 9:
                return (False, "All entries must be integers 0-9")

    # Check rows
    for i, row in enumerate(grid):
        nums = [x for x in row if x != 0]
        if len(set(nums)) != len(nums):
            return (False, f"Duplicate in row {i+1}")
        if any(not 1 <= x <= 9 for x in nums):
            return (False, f"Invalid number in row {i+1}")

    # Check columns
    for j in range(9):
        column = [grid[i][j] for i in range(9)]
        nums = [x for x in column if x != 0]
        if len(set(nums)) != len(nums):
            return (False, f"Duplicate in column {j+1}")
        if any(not 1 <= x <= 9 for x in nums):
            return (False, f"Invalid number in column {j+1}")

    # Check 3x3 sub-boxes
    for box_i in range(3):
        for box_j in range(3):
            box = [
                grid[3*box_i + i][3*box_j + j]
                for i in range(3)
                for j in range(3)
            ]
            nums = [x for x in box if x != 0]
            if len(set(nums)) != len(nums):
                return (False, f"Duplicate in box ({box_i+1}, {box_j+1})")
            if any(not 1 <= x <= 9 for x in nums):
                return (False, f"Invalid number in box ({box_i+1}, {box_j+1})")

    return (True, "Valid Sudoku configuration")

# Test with previous grids plus new edge cases
